-- ==============================================================================
-- Civic Guard — Seed 005: 25 Districts, 25 District Response Officers & 250 Field Crews
-- Comprehensive nationwide hierarchical coverage across Sri Lanka
-- ==============================================================================

-- 1. SEED 25 DISTRICTS
ON CONFLICT (code) DO UPDATE SET
    name = EXCLUDED.name,
    province = EXCLUDED.province,
    hq_lat = EXCLUDED.hq_lat,
    hq_lon = EXCLUDED.hq_lon,
    emergency_hotline = EXCLUDED.emergency_hotline;

-- 2. SEED 25 DISTRICT RESPONSE OFFICERS (1 Officer per District)
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    email = EXCLUDED.email,
    phone = EXCLUDED.phone,
    district = EXCLUDED.district;

-- 2.1 ASSIGN COUNCIL_OFFICER ROLE (Role ID 2)
ON CONFLICT (user_id, role_id) DO NOTHING;

-- 3. SEED 250 FIELD RESPONSE CREWS (10 Specialized Squads per District Officer)
-- 3.1 CREW LEAD USER ACCOUNTS
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    email = EXCLUDED.email,
    phone = EXCLUDED.phone,
    district = EXCLUDED.district;

-- 3.2 ASSIGN FIELD_CREW ROLE (Role ID 3)
ON CONFLICT (user_id, role_id) DO NOTHING;

-- 3.3 POPULATE 250 FIELD CREWS
ON CONFLICT (id) DO UPDATE SET
    user_id = EXCLUDED.user_id,
    officer_id = EXCLUDED.officer_id,
    crew_code = EXCLUDED.crew_code,
    crew_name = EXCLUDED.crew_name,
    specialty = EXCLUDED.specialty,
    district = EXCLUDED.district,
    phone = EXCLUDED.phone,
    equipment = EXCLUDED.equipment,
    latitude = EXCLUDED.latitude,
    longitude = EXCLUDED.longitude;
